  "四书/中庸章句.txt": {
    "chapters": [
      {
        "title": "第一章",
        "desc": "子思述所传之意，明道之本原",
        "pos": 0
      },
      {
        "title": "第二章",
        "desc": "仲尼曰君子中庸",
        "pos": 1
      },
      {
        "title": "第三章",
        "desc": "子曰中庸其至矣乎",
        "pos": 2
      },
      {
        "title": "第四章",
        "desc": "子曰道之不行也",
        "pos": 3
      },
      {
        "title": "第五章",
        "desc": "子曰道其不行矣夫",
        "pos": 4
      },
      {
        "title": "第六章",
        "desc": "子曰舜其大知也与",
        "pos": 5
      },
      {
        "title": "第七章",
        "desc": "子曰人皆曰予知",
        "pos": 6
      },
      {
        "title": "第八章",
        "desc": "子曰回之为人也",
        "pos": 7
      },
      {
        "title": "第九章",
        "desc": "子曰天下国家可均也",
        "pos": 8
      },
      {
        "title": "第十章",
        "desc": "子路问强",
        "pos": 9
      },
      {
        "title": "第十一章",
        "desc": "子曰素隐行怪",
        "pos": 10
      },
      {
        "title": "第十二章",
        "desc": "君子之道费而隐",
        "pos": 11
      },
      {
        "title": "第十三章",
        "desc": "子曰道不远人",
        "pos": 12
      },
      {
        "title": "第十四章",
        "desc": "君子素其位而行",
        "pos": 13
      },
      {
        "title": "第十五章",
        "desc": "君子之道辟如行远",
        "pos": 14
      },
      {
        "title": "第十六章",
        "desc": "子曰鬼神之为德",
        "pos": 15
      },
      {
        "title": "第十七章",
        "desc": "子曰舜其大孝也与",
        "pos": 16
      },
      {
        "title": "第十八章",
        "desc": "子曰无忧者其惟文王乎",
        "pos": 17
      },
      {
        "title": "第十九章",
        "desc": "子曰武王周公其达孝矣乎",
        "pos": 18
      },
      {
        "title": "第二十章",
        "desc": "哀公问政",
        "pos": 19
      },
      {
        "title": "第二十一章",
        "desc": "自诚明谓之性",
        "pos": 20
      },
      {
        "title": "第二十二章",
        "desc": "唯天下至诚为能尽其性",
        "pos": 21
      },
      {
        "title": "第二十三章",
        "desc": "其次致曲",
        "pos": 22
      },
      {
        "title": "第二十四章",
        "desc": "至诚之道可以前知",
        "pos": 23
      },
      {
        "title": "第二十五章",
        "desc": "诚者自成也",
        "pos": 24
      },
      {
        "title": "第二十六章",
        "desc": "故至诚无息",
        "pos": 25
      },
      {
        "title": "第二十七章",
        "desc": "大哉圣人之道",
        "pos": 26
      },
      {
        "title": "第二十八章",
        "desc": "子曰愚而好自用",
        "pos": 27
      },
      {
        "title": "第二十九章",
        "desc": "王天下有三重焉",
        "pos": 28
      },
      {
        "title": "第三十章",
        "desc": "仲尼祖述尧舜",
        "pos": 29
      },
      {
        "title": "第三十一章",
        "desc": "唯天下至圣为能聪明睿知",
        "pos": 30
      },
      {
        "title": "第三十二章",
        "desc": "唯天下至诚为能经纶天下之大经",
        "pos": 31
      },
      {
        "title": "第三十三章",
        "desc": "诗曰衣锦尚絅",
        "pos": 32
      }
    ],
    "source": "manual"
  },
