  "四书/孟子.txt": {
    "chapters": [
      {
        "title": "梁惠王章句上",
        "desc": "仁义而已，何必曰利",
        "pos": 0
      },
      {
        "title": "梁惠王章句下",
        "desc": "与民同乐，王政之始",
        "pos": 1
      },
      {
        "title": "公孙丑章句上",
        "desc": "我善养吾浩然之气",
        "pos": 2
      },
      {
        "title": "公孙丑章句下",
        "desc": "天时不如地利",
        "pos": 3
      },
      {
        "title": "滕文公章句上",
        "desc": "道性善，言必称尧舜",
        "pos": 4
      },
      {
        "title": "滕文公章句下",
        "desc": "富贵不能淫，贫贱不能移",
        "pos": 5
      },
      {
        "title": "离娄章句上",
        "desc": "不以规矩不能成方圆",
        "pos": 6
      },
      {
        "title": "离娄章句下",
        "desc": "君之视臣如手足",
        "pos": 7
      },
      {
        "title": "万章章句上",
        "desc": "大孝终身慕父母",
        "pos": 8
      },
      {
        "title": "万章章句下",
        "desc": "知人论世，以意逆志",
        "pos": 9
      },
      {
        "title": "告子章句上",
        "desc": "性犹湍水，无分于善不善",
        "pos": 10
      },
      {
        "title": "告子章句下",
        "desc": "生于忧患死于安乐",
        "pos": 11
      },
      {
        "title": "尽心章句上",
        "desc": "尽其心者知其性也",
        "pos": 12
      },
      {
        "title": "尽心章句下",
        "desc": "民为贵，社稷次之，君为轻",
        "pos": 13
      }
    ],
    "source": "manual"
  },
