  "孝经/孝经.txt": {
    "chapters": [
      {
        "title": "开宗明义章第一",
        "desc": "孝德之本，教之所由生",
        "pos": 0
      },
      {
        "title": "天子章第二",
        "desc": "天子之孝，爱敬尽于事亲",
        "pos": 1
      },
      {
        "title": "诸侯章第三",
        "desc": "诸侯之孝，在上不骄",
        "pos": 2
      },
      {
        "title": "卿大夫章第四",
        "desc": "卿大夫之孝，非法不言",
        "pos": 3
      },
      {
        "title": "士章第五",
        "desc": "士之孝，以孝事君则忠",
        "pos": 4
      },
      {
        "title": "庶人章第六",
        "desc": "庶人之孝，谨身节用以养父母",
        "pos": 5
      },
      {
        "title": "三才章第七",
        "desc": "夫孝天之经也地之义也",
        "pos": 6
      },
      {
        "title": "孝治章第八",
        "desc": "明王以孝治天下",
        "pos": 7
      },
      {
        "title": "圣治章第九",
        "desc": "圣人之德无以加于孝",
        "pos": 8
      },
      {
        "title": "纪孝行章第十",
        "desc": "孝子之事亲五者备矣",
        "pos": 9
      },
      {
        "title": "五刑章第十一",
        "desc": "五刑之属三千而罪莫大于不孝",
        "pos": 10
      },
      {
        "title": "广要道章第十二",
        "desc": "教民亲爱莫善于孝",
        "pos": 11
      },
      {
        "title": "广至德章第十三",
        "desc": "教以孝所以敬天下之为人父者",
        "pos": 12
      },
      {
        "title": "广扬名章第十四",
        "desc": "君子事亲孝故忠可移于君",
        "pos": 13
      },
      {
        "title": "谏诤章第十五",
        "desc": "父有争子则身不陷于不义",
        "pos": 14
      },
      {
        "title": "感应章第十六",
        "desc": "孝悌之至通于神明",
        "pos": 15
      },
      {
        "title": "事君章第十七",
        "desc": "君子之事上也进思尽忠",
        "pos": 16
      },
      {
        "title": "丧亲章第十八",
        "desc": "孝子之丧亲也",
        "pos": 17
      }
    ],
    "source": "manual"
  },
